--
-- Table structure for table `jjx_screen_master`
--

DROP TABLE IF EXISTS `jjx_screen_master`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `jjx_screen_master` (
  `screen_id` bigint NOT NULL AUTO_INCREMENT COMMENT '网版ID',
  `screen_no` varchar(30) NOT NULL COMMENT '网版编号（如 A0001）',
  `frame_type` varchar(5) NOT NULL COMMENT '框型：A/B/C/F/G/H',
  `content` varchar(1000) DEFAULT NULL COMMENT '网版内容记录',
  `mesh` varchar(20) DEFAULT NULL COMMENT '目数（可选）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1在用 0停用',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `product_id` bigint DEFAULT NULL COMMENT '关联产品ID（由菲林生成时有值）',
  `product_code` varchar(50) DEFAULT NULL COMMENT '关联产品编码',
  `film_id` bigint DEFAULT NULL COMMENT '来源菲林ID（engineering_film.film_id）',
  PRIMARY KEY (`screen_id`),
  UNIQUE KEY `uk_screen_no` (`screen_no`),
  KEY `idx_frame_type` (`frame_type`),
  KEY `idx_screen_film` (`film_id`),
  KEY `idx_screen_product` (`product_id`)
) ENGINE=InnoDB AUTO_INCREMENT=15219 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='网版主数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

